<?php if($page==='overview'):
 $total=$admin?(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='employee' AND active=1")->fetchColumn():null;
 $pending=0; $approved=0;
 if($ready){$q=$pdo->prepare('SELECT status,COUNT(*) n FROM hr_requests'.($admin?'':' WHERE user_id=?').' GROUP BY status');$q->execute($admin?[]:[$user['id']]);foreach($q as $r){if($r['status']==='Pending')$pending=$r['n'];if($r['status']==='Approved')$approved=$r['n'];}}
 ?><div class="stats"><section class="stat lavender"><div><?= $admin?'Active employees':'My requests' ?></div><strong><?= $admin?$total:($ready?$pending:'—') ?></strong><small><?= $admin?'Employee accounts':'Pending review' ?></small></section><section class="stat mint"><div><?= $admin?'Pending requests':'Approved requests' ?></div><strong><?= $ready?($admin?$pending:$approved):'—' ?></strong><small>Leave, attendance and helpdesk</small></section><section class="stat peach"><div>Attendance today</div><strong>—</strong><small>Biometric connection pending</small></section><section class="stat blue"><div><?= $admin?'Payroll':'My payslip' ?></div><strong>—</strong><small>Payroll setup pending</small></section></div><section class="panel"><h2>Hello, <?=h($user['name'])?>.</h2><p style="margin:12px 0">Choose a section to <?= $admin?'manage employee accounts, review requests or publish company notices.':'submit leave, request an attendance correction or contact your team.' ?></p><div class="quick-links"><a class="primary" href="?page=leaves"><?= $admin?'Review leave':'Apply for leave' ?> →</a><a class="wide-button" href="?page=announcements">Company notices →</a><a class="wide-button" href="?page=helpdesk">Helpdesk →</a></div></section>
<?php elseif($page==='employees' && $admin): ?><section class="panel"><h2>Create employee account</h2><form method="post" class="work-form"><?php token(); ?><input type="hidden" name="action" value="create_employee"><label>Full name<input name="name" maxlength="150" required></label><label>Work email<input name="email" type="email" maxlength="190" required></label><label>Initial password<input name="password" type="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><p>New accounts receive Employee access only. Share the initial password privately.</p><button class="primary" <?= !$ready?'disabled':'' ?>>Create employee</button></form></section><section class="panel"><h2>Employee directory</h2><div class="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Account status</th></tr></thead><tbody><?php foreach($pdo->query("SELECT name,email,active FROM users WHERE role='employee' ORDER BY name") as $r): ?><tr><td><?=h($r['name'])?></td><td><?=h($r['email'])?></td><td><?= $r['active']?'Active':'Inactive' ?></td></tr><?php endforeach ?></tbody></table></div></section>
<?php elseif(in_array($page,['leaves','regularisation','helpdesk'],true)):
 $kind=['leaves'=>'leave','regularisation'=>'regularisation','helpdesk'=>'helpdesk'][$page];
 if(!$admin): ?><section class="panel"><h2><?= $page==='leaves'?'Apply for leave':($page==='regularisation'?'Request attendance correction':'Submit a request') ?></h2><form class="work-form" method="post"><?php token(); ?><input type="hidden" name="action" value="request"><label>Category<select name="category"><?php foreach(($kind==='leave'?['CL','SL','PL','LWP']:($kind==='regularisation'?['Missed punch','Incorrect punch','Shift correction']:['HR','Payroll','IT','Other'])) as $c): ?><option><?=h($c)?></option><?php endforeach ?></select></label><label>Subject<input name="subject" maxlength="180" required></label><?php if($kind!=='helpdesk'): ?><div class="form-columns"><label>From<input type="date" name="start_date" required></label><label>To<input type="date" name="end_date" required></label></div><?php endif ?><label>Details<textarea name="details" maxlength="5000" required></textarea></label><p><?= $kind==='leave'?'Leave balances and holiday deductions are not configured yet. Requests require Super Admin review.':($kind==='regularisation'?'Approval records the decision; biometric punch corrections are not connected yet.':'Your request will be reviewed by the Super Admin.') ?></p><button class="primary" <?= !$ready?'disabled':'' ?>>Submit request</button></form></section><?php endif ?><section class="panel"><h2><?= $admin?'Review requests':'My request history' ?></h2><?php
