 if(!$records)echo '<p class="empty">No requests yet.</p>';foreach($records as $r): ?><article class="request-card"><div class="panel-title"><h2><?=h($r['subject'])?></h2><span class="badge"><?=h($r['status'])?></span></div><p><?=h($r['name'])?> · <?=h($r['category'])?><?php if($r['start_date']): ?> · <?=h($r['start_date'])?> to <?=h($r['end_date'])?><?php endif ?></p><p class="request-detail"><?=nl2br(h($r['details']))?></p><?php if($r['status']==='Pending'): ?><form method="post" class="inline-actions"><?php token(); ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="<?= $admin?'review':'cancel' ?>"><?php if($admin): ?><button class="primary" name="status" value="<?= $kind==='helpdesk'?'Resolved':'Approved' ?>"><?= $kind==='helpdesk'?'Resolve':'Approve' ?></button><button class="wide-button" name="status" value="Rejected">Reject</button><?php else: ?><button class="wide-button">Cancel request</button><?php endif ?></form><?php endif ?></article><?php endforeach ?></section>
